hl.window_rule({
	name = "windowrule-1",
	match = {
		class = ".*",
	},
	suppress_event = "maximize",
})

hl.window_rule({
	name = "windowrule-2",
	match = {
		class = "^(xwaylandvideobridge)$",
	},
	opacity = "0.0 override",
	no_anim = true,
	no_initial_focus = true,
	max_size = "1 1",
	no_blur = true,
	no_focus = true,
})

hl.window_rule({
	name = "windowrule-3",
	match = {
		class = "^$",
		title = "^$",
		xwayland = 1,
		float = 1,
		fullscreen = 0,
		pin = 0,
	},
	no_focus = true,
})

